package com.richfield.smartpantry;
import android.os.*;import android.widget.*;
public class RecipeDetailActivity extends BaseActivity{@Override public void onCreate(Bundle b){super.onCreate(b);Recipe r=new DatabaseHelper(this).recipe(getIntent().getLongExtra("id",-1));if(r==null){finish();return;}LinearLayout root=page(r.name);TextView ing=new TextView(this);ing.setText("INGREDIENTS\n"+pretty(r.ingredients));ing.setTextSize(17);ing.setPadding(8,12,8,24);root.addView(ing);TextView method=new TextView(this);method.setText("METHOD\n"+r.method);method.setTextSize(17);method.setPadding(8,12,8,24);root.addView(method);Button back=button("Back to suggestions");back.setOnClickListener(v->finish());root.addView(back);setContentView(root);}private String pretty(String raw){StringBuilder s=new StringBuilder();for(String x:raw.split(";")){String[] p=x.split("\\|");s.append("• ").append(p[1]).append(" ").append(p[2]).append(" ").append(p[0]).append("\n");}return s.toString();}}
